typedef struct Vector3 {
    float x, y, z;
    int flags;
} Vec3;

Vec3 origin = {0.0, 0.0, 0.0, 0};
Vec3 p;

p.x = 1.0;
p.y = 2.0;

// Accessing the struct tag directly (less common)
struct Vector3 temp = origin;
temp.flags = 1;

// Nested structure definition
struct Parent {
    int id;
    Vec3 position;
};
